  _ = `Yhteistyö myyntipaketeissa`,
  v = `Valinnainen: Voit kutsua muita kehittäjiä lisäämään pelinsä myyntipakettiisi. Myyntipaketin omistajana olet vastuussa muiden kehittäjien kanssa työskentelyn koordinoinnista. Omistajana olet myös ainoa, joka voi julkaista myyntipaketin Steamin kauppaan. Kutsutut osallistujat voivat valita, mitä peljeä tai paketteja he haluavat lisätä myyntipakettiin. Jos myyntipakettiin lisätään paketti tai aleprosentti muuttuu, kaikkien paketin yhteistyökumppanien tulee joka muutoskerta hyväksyä, että heidän pelinsä sisältyy myyntipakettiin ennen julkaisua.`,
