  N = `Näitä kauppasivuja esitellään Steamin etusivulla seuraavan ison kausialen aikaan (jos sivulla olevat pelit ovat alennuksessa). Varmista, että kaikki pelisarjasi olennaiset pelit ovat mukana.`,
