  ct = `Aletapahtuma tulee luoda kehittäjän kotisivulla (eli kehittäjän tai julkaisijan tai pelisarjan sivulla). Hae kehittäjän kotisivua nimellä alla:`,
  lt = `Syötä joko kehittäjäsivuun liittyvän ryhmän nimi tai kaupan URL-osoite, jos tämä on kuraattorin tai äskettäin luodun yhteisöryhmän tapahtuma.`,
