  dt = `Poista valittu kehittäjä ja hae toisen kehittäjän kotisivua`,
  ft = `2. Vahvista, että kehittäjän kotisivulla on otettu kumppanitapahtumat käyttöön:`,
  pt = `Kehittäjän kotisivu pitää liittää yhteistyökumppanien tapahtumien betaan, jotta tätä aletoimintoa voi käyttää. Toimintoa ei voi peruuttaa. Tämä muuttaa ilmoitusten julkaisuun käytetyn editorin, eivätkä kumppanit voi luoda enää linkitettyjä ilmoituksia. %1$s`,
  mt = `3. Syötä vaadittavat vähimmäistiedot:`,
  ht = `Kuvaava tapahtuman nimi`,
