  D_ = `Sinun on kerrottava käyttäjille täällä, jos peli asentaa huijauksenestoratkaisun asiakasohjelman tai ytimen osaksi. Jos kyseessä on itse kehittämäsi huijauksenestoratkaisu tai käyttämäsi ratkaisu ei löydy alla olevasta listasta, valitse Muu ja syötä tarvittavat tiedot.`,
