  Lv = `Vahvista, että kuvat ovat vaatimusten mukaisia ennen kuin lähetät ne tarkistettavaksi. Jos lähetetyt kuvat eivät täytä vaatimuksia, Steam-tarkistustiimi ei kelpuuta niitä, ja joudut tekemään tarvittavat korjaukset ennen seuraavaan vaiheeseen siirtymistä. Lisätietoja löytyy <1>Graafisten elementtien säännöt</1> -dokumentaatiosta.`,
  Rv = `Vahvista ja lähetä`,
