  fb = `Toiminto lisää tunnistekuvan, joka näytetään kaupassa paketin ostonäkymässä samaan tapaan kuin myyntipakettien sisältö. Ensin näytetään emopeli ja sen jälkeen pakettiin kuuluvat sovellukset kalleimmasta halvimpaan.`,
  pb = `Jätä pelin nimi pois paketin tuotelistan alusta.`,
  mb = `Turhan toiston vähentämiseksi ja luettavuuden helpottamiseksi, jätä pois pelin nimi, tyhjä tila ja välimerkit (kuten kaksoispisteet ja väliviivat) lisämateriaalien ja ääniraitojen alusta, kun ne näkyvät pakettien ostoalueella. Esimerkiksi Half-Life 2: Episode 1 näkyy nimellä Episode 1. Ainoastaan emopelin tarkka nimi, tyhjä tila ja yleiset välimerkit piilotetaan.`,
