  uC = `Tällä symbolilla merkityt paketit lisätään jo käynnissä olevaan alennukseen. Syötetyt alennukset alkavat heti tallennuksen jälkeen.`,
  dC = `Ajoitetun alennuksen johdosta paketin hinta laskee vaaditun vähimmäishinnan alle yhdessä tai useammassa valuutassa, eikä pakettia voi ostaa näissä maissa. Varmistaaksesi, että tämän paketin voi ostaa kaikkialla, alennuksen tulee olla alle %1$s %.`,
  fC = `Paketin perushinta yhdessä tai useammassa valuutassa on alle sallitun vähimmäishinnan, joten sitä ei voi ostaa niissä tai muissa maissa, joissa alennus johtaa hinnan putoamiseen vähimmäisvaatimusten alapuolelle. Varmistaaksesi, että tämän paketin voi ostaa kaikkialta, sen hinta tulee asettaa vähintään Steamin vähimmäishintaan.`,
