  CO = `Käyttö: valokeilatunnistekuvat näkyvät Steamin kotisivun yläosassa ja aiheeseen liittyvissä yhteisökeskuksissa tiettyjen kampanjoiden, kuten viikko- tai viikonlopputarjousten, aikana.`,
  wO = `Ulkoasu: esittelybannereiden alaosaan tulee automaattisesti osio, joka kertoo tarjouksen tyypin (esimerkiksi viikonlopputarjous) ja päättymisajan.`,
