  OO = `Käyttö: Pystysuorat valokeilakuvat näkyvät kotisivun Alennukset ja tapahtumat -osiossa. Elementti tarvitaan vain pelisarjan ja julkaisijan aletapahtumia varten. Yksittäiseen peliin viittaavissa valokeilakuvissa käytetään automaattisesti kaupan pystysuoraa tunnistekuvaa.`,
