  jO = `Mukana ei tule olla lisätekstiä (kuten Julkaisijan ale, Ilmainen viikonloppu tai Jopa –90 %). Elementin yläosaan lisättävä lokalisoitu banneri antaa tarvittavan kontekstin. Ainoana poikkeuksena sääntöön on Pelisarjan ale -teksti.`,
