  IO = `Ulkoasu: Saat parhaan tuloksen varmistamalla, että logoa on helppo lukea. Liitä mukaan myös markkinointikampanjan kuvaselite (tilaa ennakkoon, nyt saatavilla, tulossa pian jne.).`,
  LO = `Hinta ja toimintakehotepainikkeet ilmestyvät automaattisesti kuvan alle.`,
  RO = `Tiedostokoko alle 5 Mt, .jpg, .gif, .png`,
