  GI = `Demon sovellustunnus`,
  KI = `Nimi`,
  qI = `Sovellukset, joista on demo`,
  JI = `Tapahtumaan osallistuneet demot.`,
  YI = `Pelaajia yhteensä`,
  XI = `Demoa pelanneiden uniikkien pelaajien määrä tapahtuman aikana.`,
  ZI = `Toivelistalisäykset`,
  QI = `Pelin uudet toivelistalisäykset tapahtuman aikana.`,
  $I = `Pelaajat ja toivelistalisäykset`,
  eL = `Sisältää pelit, joita pelaajat sekä pelasivat että lisäsivät toivelistalleen tapahtuman aikana. Luku on kattava. Käyttäjäluvut lasketaan lisäksi kategorioihin Pelaajia yhteensä ja Toivelistalisäyksiä yhteensä.`,
  tL = `Sovellukset, joista on demo`,
  nL = `Pelaajia yhteensä`,
  rL = `Toivelistalisäyksiä yhteensä`,
  iL = `Pelaajat ja toivelistalisäykset`,
  aL = `Käynnit kauppasivulla tapahtumasivulta käsin`,
  oL = `Next Fest -sivulta lähtöisin olevat käynnit pelin kauppasivulla tapahtuman aikana. Näytetään vain peleille, joiden markkinointiliikennettä voidaan tarkastella.`,
  sL = `Käynnit kauppasivulla tapahtuman aikana`,
  cL = `Kaikki Steamistä ja muualta verkosta lähtöisin olevat käynnit pelin kauppasivulla tapahtuman aikana. Näytetään vain peleille, joiden markkinointiliikennettä voidaan tarkastella.`,
  lL = `Löytöjono: uudet uniikit pelaajat`,
  uL = `%1$s uutta uniikkia pelaajaa %2$s`,
  dL = `Näytä taloustiedot ei saatavilla`,
  fL = `Ladataan sovellusta: (%1$s)`,
  pL = `Lisätietoa Steamworks-tilin hallinnoinnista seuraavassa dokumentaatiossa.`,
  mL = `Steam Next Fest`,
  hL = `Lisätietoja Steam Next Festistä saat dokumentaatiosta täältä:`,
  gL = `Steam Next Fest -dokumentaatio`,
  _L = `Mikään peleistäsi ei ole viime aikoina osallistunut Next Festiin.`,
  vL = `Omat yhteenvedot`,
  yL = `Klikkaa Next Festin versiota alla nähdäksesi tarkemmat tiedot pelisi menestymisestä.`,
  bL = `Omat pelit:`,
  xL = `Lisää pelisarjan/kehittäjän/julkaisijan tuotteita`,
  SL = `Sovelluksellesi ei ole luotu yhtään kehittäjän kotisivua. Lue dokumentaatiosta, miten sovellukselle luodaan <1>kehittäjän tai julkaisijan sivu<1> tai <2>pelisarjan sivu</2>.`,
  CL = `Valitse aiheeseen liittyvä kehittäjän kotisivu, jonka tuotteet tulevat näkyviin kauppasivulla. Tämä osio tulee näkymään pelin kuvauksen alapuolella.`,
  wL = `Valittu kotisivu:`,
  TL = `Valittu lähde:`,
  EL = `Lajitteluperuste:`,
  DL = `Valitse niiden tuotteiden näyttämisjärjestys, jotka eivät ole Esittelyssä-kohdassa.`,
