  gq = `Virheellinen käyttöoikeus. Saavutukselle ja tilastolle on annettava sama käyttöoikeus.`,
  _q = `Virheellinen kokonaisluku. Arvon on oltava kokonaisluku, kun tilaston tyypiksi on valittu kokonaisluku.`,
  vq = `Virheellinen edistymisväli. Enimmäisarvon on oltava vähimmäisarvoa suurempi.`,
  yq = `Virheellinen edistymisen vähimmäisarvo. Saavutuksen edistymisen vähimmäisarvon on oltava suurempi tai yhtä suuri kuin tilaston vähimmäisarvo.`,
  bq = `Virheellinen ryhmän tunnus. Tunnusta ei ole olemassa.`,
  xq = `Järjestä ryhmät uudelleen`,
  Sq = `Vedä ja pudota saavutusryhmiä määrittääksesi käyttäjille näytettävän järjestyksen.`,
  Cq = `Oletusryhmää ei voi siirtää`,
