  Aq = `Saavutus puuttuu palvelimelle ladatusta CSV-määritystiedostosta, joten sen lokalisointia ei päivitetä. Lisää saavutus CSV-tiedostoon tai poista sen lokalisointimerkkijonot tiedostosta.`,
